#include <cstdint>
#include <iostream>

constexpr std::uint32_t ctlCode(std::uint32_t d, std::uint32_t f, std::uint32_t m, std::uint32_t a)
{
    return d << 16 | a << 14 | f << 2 | m;
}

constexpr std::uint32_t IOCTL_GET_STATS{ctlCode(0x8000, 0x800, 0, 0)};

struct StatsRequest
{
    std::uint32_t size;
    std::uint32_t version;
};

static_assert(sizeof(StatsRequest) == 8);

int main()
{
    std::cout << std::hex << IOCTL_GET_STATS << '\n';
}
